    The following statements are equivalent:
    \begin{itemize}
        \par\hangindent 40\p@[i.] $(x^*,y^*)\in \Delta_n\times P'_s(G)$ is a local maximizer of (\ref{general_regularized_formulation_MsPP});
        \par\hangindent 40\p@[ii.] $(x^*,y^*)\in \Delta_n\times P'_s(G)$ is a strict local maximizer of (\ref{general_regularized_formulation_MsPP});
        \par\hangindent 40\p@[iii.] $y^*$ is binary and $x^*=x(C)$ for $C$ an $s$-plex in $G$ which corresponds to a maximal clique in the auxiliary graph $G^*$ induced by $y^*$. Moreover $y^*_{ij} = 1$ for every $\{i,j\} \in \bar{E}(C)$.
    \end{itemize}
    In either of these equivalent cases we have that
   $h_G(x^*,y^*) = 1 - \frac{1}{|C|} + \Phi(x(C)).
   $

\fbox{$(i)\Longrightarrow(iii)$}  Let $(x^*,y^*)\in \Delta_n\times P'_s(G)$ be a local maximizer of (\ref{general_regularized_formulation_MsPP}). First, we want to show that $y^*\in P_s(G)$. In order to do this, let us fix the $x$-component of the problem, so $x\equiv x^*$, thus deriving the following optimization problem in the single $y$ variable:
    \begin{align}\@bsphack
  \protected@write\@auxout{} 
         {\string 
  \@ifundefined{r@general_regularized_formulation_x_fixed} 
    \relax
    {\gdef \relax { 
      \@latex@warning@no@line{Label `general_regularized_formulation_x_fixed' multiply defined}} 

   \GenericError{ 
      \space\space\space\@spaces\@spaces\@spaces
