  \global\@namedef{r@general_regularized_formulation_x_fixed}{{\p@equationSM\arabic{equation}}{SM\arabic{page}}}} 
  \@esphack
        \begin{split}
            &\max\quad g_G(y)  \\
            &s.t.\quad\ \ y\in P'_s(G),
        \end{split}
    \end{align}
    where the objective function is given by
    \begin{align*}
        g_G(y) = h_G(x^*,y) = {(x^*)}^\top [A_G+A_{\bar{G}}(y)]x^* + \Phi(x^*)\ + \sum_{\{i,j\}\in\bar{E}}\psi(y_{ij}).
    \end{align*}
    Since $(x^*,y^*)$ is a local maximizer of (\ref{general_regularized_formulation_MsPP}) by assumption, $y^*$ must also be a local maximizer of (\ref{general_regularized_formulation_x_fixed}). Moreover, the objective $g_G(y)$ has a positive-definite Hessian matrix over the polytope $P'_s(G)$, since for any $\{i,j\}\in\bar{E}$ and $y\in P'_s(G)$ we have
    $
        \frac{\partial^2}{\partial y_{ij}^2}g_G(y) = \psi''(y_{ij})>0,
   $
    while for any pair of distinct missing edges $\{i,j\},\{k,l\}\in\bar{E}$ the corresponding entry is
    $
        \frac{\partial^2}{\partial y_{ij}\partial y_{kl}}g_G(y) = 0.
    $
    Hence, by Lemma \ref{max_convex_program} we can conclude that all local maximizers of (\ref{general_regularized_formulation_x_fixed}) are extreme points of the feasible region. This in particular implies that the local maximizer $y^*$  is a vertex of the polytope $P'_s(G)$. 

    On the other hand, we have already pointed out how the feasible region $P'_s(G)$ coincides with a fractional $b$-matching polytope in the complementary graph $\bar{G}$ with $b=(s-1)e$, see problem~(\ref{LR_MWBMP_fix_x*}) above. Thus, by Lemma~\ref{lemma_fractional_b-matching_polytope} we know that the vertices of $P'_s(G)$ are half-integral, i.e. $y^*_{ij}\in\big\{0,\frac{1}{2},1\big\}$ for every $\{i,j\}\in\bar{E}$. Let us assume, by contradiction, that there exists an edge $\{i,j\}\in\bar{E}$ such that $y^*_{ij}=\frac{1}{2}$ is fractional. By
Lemma~\ref{lemma_fractional_b-matching_polytope}, the fractional support of $y^*$ contains an odd cycle,
and every edge of this cycle has value $1/2$. Fix one such edge
$\{i,j\}\in\bar E$ and let
\[
\hat y:=y^*-\varepsilon\, e_{ij},
\qquad 0<\varepsilon\leq\frac12,
\]
where $e_{ij}\in\mathbb{R}^{\bar m}$ denotes the unit vector associated with the missing edge $\{i,j\}$. Since the constraints defining $P'_s(G)$ are upper-bound
constraints with non-negative coefficients, $\hat y\in P'_s(G)$. By the convexity of $\psi$,
\[
\psi\left(\frac12-\varepsilon\right)
-\psi\left(\frac12\right)
\geq
-\varepsilon\psi'\left(\frac12\right).
\]
Consequently,
\begin{align*}
g_G(\hat y)-g_G(y^*)
&=
-2\varepsilon x_i^*x_j^*
+\psi\left(\frac12-\varepsilon\right)
-\psi\left(\frac12\right)\\
&\geq
-\varepsilon\left(
2x_i^*x_j^*+\psi'\left(\frac12\right)
\right)>0,
\end{align*}
where the last inequality follows from
$2x_i^*x_j^*\leq 1/2$ and condition~(R2).
This contradicts the local optimality of $y^*$ and finally shows that  $y^*_{ij}\in\{0,1\}$ for every $\{i,j\} \in \bar{E}$, so $y^*$ is binary. \\
After showing this first property, let us fix the $y$-component of (\ref{general_regularized_formulation_MsPP}) instead, so $y\equiv y^*$. Then $x^*$ must be a local maximizer of the function 
    \begin{align*}
        h_G(x,y^*)= x^\top (A_G + A_{\bar{G}}(y^*))x + \Phi(x) = x^\top A_{G^*}x + \Phi(x)
    \end{align*}
    over the standard simplex, where $G^*$ is the auxiliary graph induced by $y^*\in P_s(G)$. As we can see, the considered optimization problem coincides with the regularized version of the maximum clique formulation (\ref{regularized_MS_MCP}) over $G^*$ given in \cite{Hungerford}, thus it must hold that $x^*=x(C)$ for $C$ a maximal clique in $G^*$. Since the auxiliary graph $G^*$ is defined by adding the missing edges in $G$ corresponding to the $\operatorname{supp}(y^*)$, then $C$ must also be an $s$-plex in $G$ and $y^*_{ij} = 1$ for all $\{i,j\}\in\bar{E}(C)$. \\


    \fbox{$(iii)\Longrightarrow(ii)$} Let $(x^*,y^*)\in\Delta_n\times P'_s(G)$ satisfy the properties outlined in the  statement $(iii)$ above. To show that it is a strict local maximizer of $(\ref{general_regularized_formulation_MsPP})$, we want to verify that the second-order sufficient optimality conditions (\ref{general_second_order_sufficient_condition_1}) and (\ref{general_second_order_sufficient_condition_2}) hold in this case. 

    For any missing edge $\{i,j\}\in\bar{E}$ we can compute 
    \begin{align*}
        \frac{\partial}{\partial y_{ij}}h_G(x^*,y^*) = 2x^*_ix^*_j + \psi'(y^*_{ij}).
    \end{align*}
    In the following we denote by $S:= \operatorname{supp}(y^*)$, and $\bar{S}:=\bar{E}\setminus S$. Since by assumption $y_{ij}^*=1$ for any $\{i,j\}\in\bar{E}(C)$, clearly $2x_l^*x_k^*=0$ for any $\{l,k\}\in\bar{S}$. Moreover, by conditions \ref{cond_R1} and \ref{cond_R3} we necessarily have $\psi'(0)<0$ and $\psi'(1)>0$. Thus, for $\{l,k\}\in\bar{S}$ we get
    \begin{align}\@bsphack
