  \@esphack
        \begin{split}
            \nabla_xh_G(x^*,y^*)^\top d_x &= (2A_Gx^*+2A_{\bar{G}}(y^*)x^*+\nabla\Phi(x^*))^\top d_x \\ &= 2x(C)^\top A_{G^*}d_x + \nabla\Phi(x(C))^\top d_x\leq0,
        \end{split}
    \end{align}
    where the inequality follows by Lemma \ref{negative_scalar_product_with_the_matrix} and Lemma \ref{negative_scalar_product_with_the_penalty_term} with respect to the MCP over the auxiliary graph $G^*$ induced by $y^*$. 

    For the $y$-component we can instead compute
    \begin{align*}
            (\bar{y} - y^*)^\top \nabla_yh_G(x^*,y^*) &= \sum_{\{i,j\}\in \bar{E}} (\bar{y}_{ij}-y^*_{ij}) \frac{\partial}{\partial y_{ij}}h_G(x^*,y^*) \\
            &= \sum_{\{i,j\}\in S} (\bar{y}_{ij}-1) \frac{\partial}{\partial y_{ij}}h_G(x^*,y^*)\ + \sum_{\{i,j\}\in\bar{S}} \bar{y}_{ij} \frac{\partial}{\partial y_{ij}}h_G(x^*,y^*)
    \end{align*}
    thus
    \begin{align}\@bsphack
